"""Original English starter curriculum. Regenerate public/learning-data.json after edits."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
LANGUAGES = {'python': 'Python', 'cpp': 'C++', 'c': 'C', 'javascript': 'JavaScript', 'java': 'Java', 'go': 'Go', 'ruby': 'Ruby', 'sql': 'SQL'}

def wrap(lang, body, functions=''):
    if lang == 'cpp':
        return '#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\n' + functions + '\nint main() {\n' + '\n'.join(('    ' + line for line in body.splitlines())) + '\n    return 0;\n}\n'
    if lang == 'c':
        return '#include <stdio.h>\n#include <string.h>\n\n' + functions + '\nint main(void) {\n' + '\n'.join(('    ' + line for line in body.splitlines())) + '\n    return 0;\n}\n'
    if lang == 'java':
        return 'import java.util.*;\n\npublic class Main {\n' + functions + '\n    public static void main(String[] args) {\n' + '\n'.join(('        ' + line for line in body.splitlines())) + '\n    }\n}\n'
    if lang == 'go':
        return 'package main\n\nimport "fmt"\n\n' + functions + '\nfunc main() {\n' + '\n'.join(('    ' + line for line in body.splitlines())) + '\n}\n'
    return functions + ('\n' if functions else '') + body + '\n'
snippets = {'python': [('age = 19\nname = "Ali"\nprint(name)\nprint(age)', ''), ('score = 85\nif score >= 60:\n    print("Passed")\nelse:\n    print("Try again")', ''), ('total = 0\nfor n in range(1, 6):\n    total += n\nprint(total)', ''), ('print(square(6))', 'def square(n):\n    return n * n\n')], 'cpp': [('int age = 19;\nstring name = "Ali";\ncout << name << "\\n" << age << "\\n";', ''), ('int score = 85;\nif (score >= 60) {\n    cout << "Passed\\n";\n} else {\n    cout << "Try again\\n";\n}', ''), ('int total = 0;\nfor (int n = 1; n <= 5; n++) total += n;\ncout << total << "\\n";', ''), ('cout << square(6) << "\\n";', 'int square(int n) { return n * n; }\n')], 'c': [('int age = 19;\nchar name[] = "Ali";\nprintf("%s\\n%d\\n", name, age);', ''), ('int score = 85;\nif (score >= 60) {\n    printf("Passed\\n");\n} else {\n    printf("Try again\\n");\n}', ''), ('int total = 0;\nfor (int n = 1; n <= 5; n++) total += n;\nprintf("%d\\n", total);', ''), ('printf("%d\\n", square(6));', 'int square(int n) { return n * n; }\n')], 'javascript': [('let age = 19;\nconst name = "Ali";\nconsole.log(name);\nconsole.log(age);', ''), ('const score = 85;\nif (score >= 60) {\n    console.log("Passed");\n} else {\n    console.log("Try again");\n}', ''), ('let total = 0;\nfor (let n = 1; n <= 5; n++) total += n;\nconsole.log(total);', ''), ('console.log(square(6));', 'function square(n) {\n    return n * n;\n}\n')], 'java': [('int age = 19;\nString name = "Ali";\nSystem.out.println(name);\nSystem.out.println(age);', ''), ('int score = 85;\nif (score >= 60) {\n    System.out.println("Passed");\n} else {\n    System.out.println("Try again");\n}', ''), ('int total = 0;\nfor (int n = 1; n <= 5; n++) total += n;\nSystem.out.println(total);', ''), ('System.out.println(square(6));', '    static int square(int n) { return n * n; }\n')], 'go': [('age := 19\nname := "Ali"\nfmt.Println(name)\nfmt.Println(age)', ''), ('score := 85\nif score >= 60 {\n    fmt.Println("Passed")\n} else {\n    fmt.Println("Try again")\n}', ''), ('total := 0\nfor n := 1; n <= 5; n++ {\n    total += n\n}\nfmt.Println(total)', ''), ('fmt.Println(square(6))', 'func square(n int) int {\n    return n * n\n}\n')], 'ruby': [('age = 19\nname = "Ali"\nputs name\nputs age', ''), ('score = 85\nif score >= 60\n    puts "Passed"\nelse\n    puts "Try again"\nend', ''), ('total = 0\n(1..5).each do |n|\n    total += n\nend\nputs total', ''), ('puts square(6)', 'def square(n)\n    n * n\nend\n')]}
topics = [('variables', 'Variables and types', 'Give your data a name', ['A variable gives a value a name. You can use that name to work with the value later in your program.', 'In this example, name stores text and age stores a whole number. Text is written inside quotation marks; numbers are written without them.', 'Open the code and change the name and age. The output shows the name first, then the age on a separate line.'], 'Ali\n19\n', 'Change the age to 21. Notice the difference between writing a number and writing text.', 'Which value is an integer?', ['"19"', '19', '"Ali"'], 1, 'Without quotation marks, 19 is an integer. "19" is a string.'), ('conditions', 'Conditions: if / else', 'Teach your program to make choices', ['A condition is an expression that evaluates to true or false. An if statement runs one block when the condition is true and an else block otherwise.', 'The expression score >= 60 checks whether the score is at least 60. A score of 85 produces Passed.', 'Test values at the boundary too: 59, 60, and 61. One successful example is not enough to check your condition.'], 'Passed\n', 'Set the score to 59. Then try 60 to check the boundary condition.', 'If score is 60, is score >= 60 true?', ['Yes', 'No', 'Only when score > 60'], 0, 'The >= operator includes equality, so the condition is true for 60.'), ('loops', 'Loops and sums', 'Make repetitive work simpler', ['A loop repeats an operation. As the counter changes, each iteration works with a new value.', 'The variable total starts at 0. Adding 1, 2, 3, 4, and 5 gives a final sum of 15.', 'Identify where the loop starts and stops. An incorrect stopping condition can cause extra iterations or an infinite loop.'], '15\n', 'Change the upper limit to 10. The sum of the numbers from 1 to 10 should be 55.', 'What is 1 + 2 + 3 + 4 + 5?', ['10', '15', '25'], 1, 'The five numbers add up to 15. The last counter value is not the sum.'), ('functions', 'Functions', 'Write once, use again', ['A function is a named group of operations. It can accept values through parameters and return a result.', 'The square function multiplies n by itself. Calling square(6) returns 36, which is then printed.', 'Returning a value and printing it are different operations. A returned value can be used in other calculations.'], '36\n', 'Call square(9). Then write a cube function that raises a number to the third power.', 'What does square(6) return?', ['12', '36', '216'], 1, 'Squaring multiplies a number by itself: 6 × 6 = 36.')]
notes = {'python': ['Python determines the type from the value. age = "19" stores a string, not a number.', 'Python uses indentation to define blocks. Both if and else need a colon.', 'range(1, 6) does not include 6; the last value is 5.', 'def defines a function; return sends its result back to the caller.'], 'cpp': ['Use int for whole numbers and string for text. Execution starts in main.', '== compares values; = assigns a value. Do not confuse them.', 'n <= 5 includes the final value. n++ increases the counter by one.', 'The function is defined before it is called in this example. Its return type is int.'], 'c': ['In C, a simple string is represented by a char array. printf needs format specifiers.', 'Use braces around conditional blocks to make later changes less error-prone.', 'C17 allows you to declare int n inside a for loop.', 'Both the parameter and return value have type int.'], 'javascript': ['A const binding cannot be reassigned; let allows reassignment.', 'Use === when you need strict equality comparisons.', 'JavaScript runs in Node.js here. document and alert are browser APIs.', 'Without a return statement, a function returns undefined.'], 'java': ['Java declares types explicitly. Use the file Main.java and the public class Main.', 'Put the condition in parentheses and strings in double quotation marks.', 'System.out.println adds a new line after the value.', 'The static function can be called from static main without creating an object.'], 'go': [':= declares a new variable inside a function. Declared local variables must be used.', 'Go does not require parentheses around an if condition. Put the opening brace on the same line.', 'Go uses for for loops. In this example, n goes from 1 to 5.', 'Go writes a parameter type after its name and the return type after the parameter list.'], 'ruby': ['Ruby determines types from values. puts adds a new line after each value.', 'Ruby ends an if block with end.', '(1..5) includes 5; (1...5) does not.', 'Ruby automatically returns the last expression. You can also use return.']}
lessons = []
for lang in snippets:
    for index, (topic, title, desc, paragraphs, output, exercise, question, choices, answer, explanation) in enumerate(topics):
        code = wrap(lang, *snippets[lang][index])
        lessons.append(dict(id=f'{lang}-{topic}', language=lang, title=title, summary=desc, order=index + 1, minutes=5 + index, level='Beginner', paragraphs=paragraphs, note=notes[lang][index], code=code, output=output, stdin='', exercise=exercise, quiz=dict(question=question, choices=choices, answer=answer, explanation=explanation)))
sql_setup = "CREATE TABLE students (name TEXT, score INTEGER);\nINSERT INTO students VALUES ('Ali', 85), ('Lola', 95), ('Vali', 55);\n\n"
sql_topics = [('tables', 'Tables and data', 'CREATE TABLE and INSERT', ['SQL stores data in tables. Each column defines a type of data, and each row represents a record.', 'CREATE TABLE defines a table, INSERT INTO adds rows, and SELECT reads the data.'], sql_setup + 'SELECT name, score FROM students ORDER BY name;\n', 'name  score\n----  -----\nAli   85\nLola  95\nVali  55\n', 'Add another student and inspect the result.', 'Which statement adds a row?', ['SELECT', 'INSERT INTO', 'ORDER BY'], 1, 'INSERT INTO adds a new row.'), ('filter', 'Sorting and filtering', 'WHERE and ORDER BY', ['WHERE chooses which rows to include. ORDER BY controls the order of the results.', 'This example selects students with a score of at least 60 and orders them by score from highest to lowest. DESC means descending; ASC means ascending.'], sql_setup + 'SELECT name, score FROM students\nWHERE score >= 60\nORDER BY score DESC;\n', 'name  score\n----  -----\nLola  95\nAli   85\n', 'Change the threshold to 90. Only one student should remain.', 'Which keyword specifies descending order?', ['ASC', 'DESC', 'WHERE'], 1, 'DESC orders values from highest to lowest.'), ('aggregate', 'Aggregation and grouping', 'COUNT, AVG, and GROUP BY', ['Aggregate functions calculate one value from several rows. COUNT counts rows and AVG calculates an average.', 'GROUP BY puts rows with the same key into groups. Use HAVING to filter the resulting groups.'], sql_setup + 'SELECT COUNT(*) AS count, ROUND(AVG(score), 2) AS average FROM students;\n', 'count  average\n-----  -------\n3      78.33\n', 'Add columns for MAX(score) and MIN(score).', 'Which expression counts rows?', ['AVG(score)', 'COUNT(*)', 'ORDER BY'], 1, 'COUNT(*) counts all selected rows.'), ('join', 'Joining tables', 'INNER JOIN', ['JOIN combines related data from two tables. ON specifies which column values must match.', 'INNER JOIN returns matching rows from both tables. LEFT JOIN also preserves unmatched rows from the left table.'], "CREATE TABLE groups (id INTEGER, title TEXT);\nCREATE TABLE students (name TEXT, group_id INTEGER);\nINSERT INTO groups VALUES (1, 'CS-101'), (2, 'CS-102');\nINSERT INTO students VALUES ('Ali', 1), ('Lola', 2);\nSELECT s.name, g.title\nFROM students AS s JOIN groups AS g ON s.group_id = g.id\nORDER BY s.name;\n", 'name  title\n----  ------\nAli   CS-101\nLola  CS-102\n', 'Add a student with a nonexistent group. Compare INNER JOIN with LEFT JOIN.', 'Which join preserves unmatched rows from the left table?', ['INNER JOIN', 'LEFT JOIN', 'CROSS JOIN'], 1, 'LEFT JOIN preserves every row from the left table.')]
for i, (topic, title, desc, paragraphs, code, output, exercise, q, choices, answer, explanation) in enumerate(sql_topics):
    lessons.append(dict(id='sql-' + topic, language='sql', title=title, summary=desc, order=i + 1, minutes=6 + i, level='Beginner', paragraphs=paragraphs, note='Each run starts with a fresh SQLite database. Create the tables you need in the same source file.', code=code, output=output, stdin='', exercise=exercise, quiz=dict(question=q, choices=choices, answer=answer, explanation=explanation)))
examples = [dict(id='example-' + l['id'], language=l['language'], title=l['title'], category='Fundamentals' if l['language'] != 'sql' else 'Databases', summary=l['summary'], code=l['code'], stdin=l['stdin'], output=l['output']) for l in lessons]
inputs = {'python': 'n = int(input())\nprint(n * 2)\n', 'cpp': wrap('cpp', 'int n;\ncin >> n;\ncout << n * 2 << "\\n";'), 'c': wrap('c', 'int n;\nif (scanf("%d", &n) == 1) printf("%d\\n", n * 2);'), 'javascript': 'const fs = require("node:fs");\nconst n = Number(fs.readFileSync(0, "utf8").trim());\nconsole.log(n * 2);\n', 'java': wrap('java', 'Scanner scanner = new Scanner(System.in);\nint n = scanner.nextInt();\nSystem.out.println(n * 2);'), 'go': wrap('go', 'var n int\nfmt.Scan(&n)\nfmt.Println(n * 2)'), 'ruby': 'n = gets.to_i\nputs n * 2\n', 'sql': 'SELECT 21 * 2 AS doubled;\n'}
for lang, code in inputs.items():
    examples.append(dict(id='example-' + lang + '-double', language=lang, title='Double a number', category='Input / output' if lang != 'sql' else 'Databases', summary='Read a number from standard input and calculate its double.' if lang != 'sql' else 'Calculate a number using a SQL expression.', code=code, stdin='21\n' if lang != 'sql' else '', output='42\n' if lang != 'sql' else 'doubled\n-------\n42\n'))
refdata = {'python': [('print()', 'print(value)', 'Prints a value to the console.', 'print("Hello")', 'Adds a new line by default. Use the end parameter to change it.'), ('len()', 'len(collection)', 'Returns the length of a string or collection.', 'len([10, 20, 30])  # 3', 'Indexes start at 0. The last index is one less than the length.'), ('range()', 'range(start, stop, step)', 'Represents a sequence of integers.', 'list(range(1, 6))  # [1, 2, 3, 4, 5]', 'The stop value is excluded. The step cannot be 0.'), ('list.append()', 'items.append(value)', 'Adds an element to the end of a list.', 'items = [1, 2]\nitems.append(3)', 'Modifies the existing list; it does not return a new list.')], 'cpp': [('cout', 'cout << value;', 'Writes a value to standard output.', 'cout << "Hello" << "\\n";', 'Requires <iostream>. Use std::cout or a using declaration.'), ('cin', 'cin >> variable;', 'Reads a formatted value from standard input.', 'int age;\ncin >> age;', 'Reads whitespace-separated values. Use getline to read a whole line.'), ('vector.push_back()', 'items.push_back(value);', 'Adds an element to the end of a vector.', 'vector<int> items = {1, 2};\nitems.push_back(3);', 'Requires <vector>. Appending has amortized O(1) time complexity.'), ('string.size()', 'text.size()', 'Returns the size of a string.', 'string text = "Hello";\ncout << text.size();', 'For UTF-8 strings, the byte count is not always the number of characters.')], 'c': [('printf()', 'printf(format, values);', 'Prints values using a format string.', 'printf("%d\\n", 42);', 'Use %d for int and %s for a null-terminated string. Requires <stdio.h>.'), ('scanf()', 'scanf(format, addresses);', 'Reads values from standard input.', 'int n;\nif (scanf("%d", &n) == 1) printf("%d", n);', 'Check the return value. When reading strings, limit the field width to fit the buffer.'), ('strlen()', 'strlen(text)', 'Returns the length of a null-terminated string.', 'size_t n = strlen("Hello");', 'Requires <string.h>. The terminating null byte is not counted.'), ('sizeof', 'sizeof(value_or_type)', 'Gives the size of an object or type in bytes.', 'size_t count = sizeof(int);', 'This is an operator, not a function. sizeof(pointer) does not give the length of an array.')], 'javascript': [('console.log()', 'console.log(value);', 'Prints a value to the console.', 'console.log("Hello");', 'JavaScript runs in a Node.js environment in this compiler.'), ('Array.map()', 'items.map(callback)', 'Creates a new array by transforming each element.', '[1, 2, 3].map(n => n * 2);', 'The result is [2, 4, 6]. This example does not modify the original array.'), ('Array.filter()', 'items.filter(predicate)', 'Creates a new array containing elements that pass a test.', '[1, 2, 3, 4].filter(n => n % 2 === 0);', 'The result is [2, 4]. An element is kept when the callback returns a truthy value.'), ('JSON.parse()', 'JSON.parse(text)', 'Converts JSON text into a JavaScript value.', 'JSON.parse(\'{"score":85}\');', 'Invalid JSON throws a SyntaxError. Use try/catch when appropriate.')], 'java': [('println()', 'System.out.println(value);', 'Prints a value followed by a new line.', 'System.out.println("Hello");', 'print does not add a new line; println does.'), ('Scanner.nextInt()', 'scanner.nextInt()', 'Reads the next integer.', 'Scanner scanner = new Scanner(System.in);\nint n = scanner.nextInt();', 'Requires import java.util.Scanner. Invalid input may throw an exception.'), ('String.length()', 'text.length()', 'Returns the string length in UTF-16 code units.', '"Hello".length();  // 5', 'This is not always the number of visible Unicode characters.'), ('ArrayList.add()', 'items.add(value);', 'Adds an element to a dynamic list.', 'ArrayList<Integer> items = new ArrayList<>();\nitems.add(42);', 'Requires import java.util.ArrayList. Use Integer rather than int for the type parameter.')], 'go': [('fmt.Println()', 'fmt.Println(values...)', 'Prints values followed by a new line.', 'fmt.Println("Hello", 42)', 'Requires import "fmt". Inserts spaces between values.'), ('fmt.Scan()', 'fmt.Scan(&variable)', 'Reads a value from standard input.', 'var n int\nfmt.Scan(&n)', 'Returns the number of items read and an error. Check the error in real applications.'), ('append()', 'append(slice, value)', 'Appends an element and returns the updated slice.', 'items := []int{1, 2}\nitems = append(items, 3)', 'Save the returned slice; its backing array may have been reallocated.'), ('len()', 'len(value)', 'Returns the length of a slice, map, array, or string.', 'fmt.Println(len([]int{1, 2, 3}))', 'For strings, len counts bytes, not Unicode characters.')], 'ruby': [('puts', 'puts value', 'Prints a value followed by a new line.', 'puts "Hello"', 'print usually does not add a new line.'), ('gets', 'gets', 'Reads one line from standard input.', 'name = gets&.chomp', 'May return nil at the end of input. chomp removes the trailing record separator.'), ('Array#map', 'items.map { |x| expression }', 'Creates a new array from the results of a block.', '[1, 2, 3].map { |n| n * 2 }', 'The result is [2, 4, 6]. map! changes the original array instead.'), ('Array#select', 'items.select { |x| condition }', 'Selects elements that satisfy a condition.', '[1, 2, 3, 4].select { |n| n.even? }', 'The result is [2, 4].')], 'sql': [('SELECT', 'SELECT columns FROM table_name;', 'Reads columns from a table.', 'SELECT name, score FROM students;', 'Do not rely on row order without ORDER BY.'), ('WHERE', 'WHERE condition', 'Filters rows using a condition.', 'SELECT name FROM students WHERE score >= 60;', 'Check for NULL with IS NULL, not = NULL.'), ('GROUP BY', 'GROUP BY column', 'Groups rows for aggregate calculations.', 'SELECT group_id, COUNT(*) FROM students GROUP BY group_id;', 'WHERE filters rows; HAVING filters the calculated groups.'), ('JOIN', 'JOIN other_table ON condition', 'Combines related tables.', 'SELECT s.name, g.title FROM students s JOIN groups g ON s.group_id = g.id;', 'Multiple matches can increase the number of rows in the result.')]}
references = []
for lang, entries in refdata.items():
    for i, (title, syntax, summary, example, note) in enumerate(entries):
        references.append(dict(id=f'{lang}-ref-{i}', language=lang, title=title, syntax=syntax, summary=summary, example=example, note=note))
algorithms = []

def alg(id, title, summary, complexity, space, steps, code, output, note, kind):
    algorithms.append(dict(id=id, title=title, summary=summary, complexity=complexity, space=space, steps=steps, code=code, output=output, language='python', stdin='', note=note, category=kind))
alg('linear-search', 'Linear search', 'Check elements one by one from start to finish.', 'O(n)', 'O(1)', ['Start at index 0.', 'Compare each element with the target.', 'Return the index when a match is found; otherwise continue.', 'Return -1 if you reach the end without a match.'], 'def find(items, target):\n    for i, value in enumerate(items):\n        if value == target:\n            return i\n    return -1\n\nprint(find([8, 3, 5, 1], 5))\n', '2\n', 'The array does not need to be sorted. If values repeat, this implementation returns the first matching index.', 'Search')
alg('binary-search', 'Binary search', 'Halve the search interval in a sorted array.', 'O(log n)', 'O(1)', ['The array must be sorted in ascending order.', 'Calculate the middle index from the left and right boundaries.', 'If the middle value is smaller, move the left boundary up; if larger, move the right boundary down.', 'Return the index when found, or -1 when the interval is empty.'], 'def binary_search(items, target):\n    left, right = 0, len(items) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if items[mid] == target:\n            return mid\n        if items[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1\n\nprint(binary_search([1, 3, 5, 7, 9], 7))\n', '3\n', 'This algorithm does not guarantee a correct answer on an unsorted array. Indexes start at 0.', 'Search')
alg('bubble-sort', 'Bubble sort', 'Compare neighboring elements and move larger values to the right.', 'O(n²), best case O(n)', 'O(1)', ['Compare two neighboring elements.', 'Swap them if the left value is larger.', 'After one pass, the largest remaining value reaches the end.', 'Stop early when a pass makes no swaps.'], 'items = [5, 2, 4, 1]\nfor end in range(len(items) - 1, 0, -1):\n    changed = False\n    for i in range(end):\n        if items[i] > items[i + 1]:\n            items[i], items[i + 1] = items[i + 1], items[i]\n            changed = True\n    if not changed:\n        break\nprint(items)\n', '[1, 2, 4, 5]\n', 'Useful for learning. For large datasets, usually prefer the sorting tools provided by the language.', 'Sorting')
alg('stack', 'Stack — LIFO', 'The last element added is the first one removed.', 'Push/pop at the end: amortized O(1)', 'O(n) for n elements', ['Create an empty stack.', 'Push an element onto the end.', 'Pop the last element.', 'Check that the stack is not empty before removing an element.'], 'stack = []\nstack.append("A")\nstack.append("B")\nprint(stack.pop())\nprint(stack.pop())\n', 'B\nA\n', 'Popping from the end of a Python list works well for stacks. Calling pop() on an empty list raises IndexError.', 'Data structures')
alg('queue', 'Queue — FIFO', 'The first element added is the first one removed.', 'deque.append / popleft: O(1)', 'O(n) for n elements', ['Create an empty queue.', 'Add an element at the end.', 'Remove an element from the front.', 'Use deque for efficient removal from the front.'], 'from collections import deque\n\nqueue = deque(["Ali", "Lola"])\nqueue.append("Vali")\nprint(queue.popleft())\nprint(queue.popleft())\n', 'Ali\nLola\n', 'list.pop(0) takes O(n) time; deque.popleft() is better suited to a queue.', 'Data structures')
alg('hash-map', 'Dictionary — hash map', 'Look up values by key and count repeated items.', 'Lookup/insertion: average O(1), worst case O(n)', 'O(n)', ['Use each value as a key.', 'Start the count at 0 if the key is missing.', 'Increase the count at each occurrence.', 'Read the result using the key.'], 'counts = {}\nfor word in ["apple", "pomegranate", "apple"]:\n    counts[word] = counts.get(word, 0) + 1\nprint(counts["apple"])\n', '2\n', 'Python dictionary keys must be hashable. A list, for example, cannot be used as a key.', 'Data structures')
alg('linked-list', 'Linked list', 'Each node stores a value and a reference to the next node.', 'Insert at head: O(1), search: O(n)', 'O(n)', ['Store value and next fields in a Node class.', 'Keep a head reference to the first node.', 'Follow next to move to the next node.', 'Stop when you reach None.'], 'class Node:\n    def __init__(self, value, next_node=None):\n        self.value = value\n        self.next = next_node\n\nhead = Node(10, Node(20, Node(30)))\ncurrent = head\nwhile current is not None:\n    print(current.value)\n    current = current.next\n', '10\n20\n30\n', 'There is no direct indexed access: you must walk through the list to reach the desired node.', 'Data structures')
alg('bfs', 'Breadth-first search (BFS)', 'Visit a graph layer by layer from a starting node.', 'O(V + E)', 'O(V)', ['Add the starting node to the queue and the visited set.', 'Remove the node at the front of the queue.', 'Mark unvisited neighbors and add them to the queue.', 'Continue until the queue is empty.'], 'from collections import deque\n\ngraph = {"A": ["B", "C"], "B": ["D"], "C": [], "D": []}\nqueue = deque(["A"])\nvisited = {"A"}\norder = []\nwhile queue:\n    node = queue.popleft()\n    order.append(node)\n    for neighbor in graph[node]:\n        if neighbor not in visited:\n            visited.add(neighbor)\n            queue.append(neighbor)\nprint(" ".join(order))\n', 'A B C D\n', 'V is the number of vertices and E is the number of edges. This implementation visits only the part reachable from the starting node.', 'Graphs')
data = dict(languages=LANGUAGES, lessons=lessons, examples=examples, references=references, algorithms=algorithms)
(ROOT / 'public/learning-data.json').write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
print({key: len(data[key]) for key in ('lessons', 'examples', 'references', 'algorithms')})
